// src/crypto/decrypt.controller.ts
import { Controller, Post, Body, Res, HttpStatus } from '@nestjs/common';
import { Response } from 'express';
import * as crypto from 'crypto';

const ALGORITHM = 'aes-256-cbc';
const KEY = Buffer.from(process.env.ENCRYPTION_KEY || 'a'.repeat(64), 'hex');

interface DecryptRequest {
  ciphertext: string; // base64 encoded
  iv: string;        // base64 encoded
}

@Controller('api/v2/decrypt')
export class DecryptController {

  @Post()
  async decrypt(@Body() body: DecryptRequest, @Res() res: Response) {
    try {
      const ciphertext = Buffer.from(body.ciphertext, 'base64');
      const iv = Buffer.from(body.iv, 'base64');

      if (iv.length !== 16) {
        return res.status(HttpStatus.BAD_REQUEST).json({
          error: 'Invalid IV length'
        });
      }

      const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
      // PKCS7 padding is validated automatically by OpenSSL
      let decrypted = decipher.update(ciphertext);
      decrypted = Buffer.concat([decrypted, decipher.final()]);

      return res.status(HttpStatus.OK).json({
        plaintext: decrypted.toString('utf8'),
        status: 'success'
      });
    } catch (err: any) {
      // Vulnerability: Different error responses for padding vs other errors
      // This leaks padding validity information to the attacker
      if (err.message && err.message.includes('bad decrypt')) {
        return res.status(HttpStatus.BAD_REQUEST).json({
          error: 'Decryption failed: invalid padding',
          code: 'ERR_PADDING_INVALID'
        });
      }
      if (err.message && err.message.includes('wrong final block')) {
        return res.status(HttpStatus.BAD_REQUEST).json({
          error: 'Decryption failed: block alignment error',
          code: 'ERR_BLOCK_ALIGN'
        });
      }
      return res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({
        error: 'Internal server error',
        code: 'ERR_INTERNAL'
      });
    }
  }
}

