@Controller('api/v2/token')
export class TokenController {

  @Post('verify')
  async verifyToken(@Body() body: { token: string }, @Res() res: Response) {
    try {
      const parts = body.token.split('.');
      if (parts.length !== 3) {
        return res.status(HttpStatus.BAD_REQUEST).json({ valid: false });
      }
      const [ivB64, ciphertextB64, hmacB64] = parts;
      const iv = Buffer.from(ivB64, 'base64');
      const ciphertext = Buffer.from(ciphertextB64, 'base64');

      // Note: HMAC verification happens AFTER decryption attempt
      // This is a classic Encrypt-then-MAC implementation error
      const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
      let decrypted = decipher.update(ciphertext);
      decrypted = Buffer.concat([decrypted, decipher.final()]);

      // HMAC check (too late - padding oracle already leaked)
      const expectedHmac = crypto.createHmac('sha256', KEY)
        .update(Buffer.concat([iv, ciphertext]))
        .digest();
      const providedHmac = Buffer.from(hmacB64, 'base64');

      if (!crypto.timingSafeEqual(expectedHmac, providedHmac)) {
        return res.status(HttpStatus.UNAUTHORIZED).json({ valid: false });
      }

      return res.status(HttpStatus.OK).json({ valid: true, payload: JSON.parse(decrypted.toString()) });
    } catch (err: any) {
      if (err.message?.includes('bad decrypt') || err.message?.includes('wrong final')) {
        return res.status(422).json({ valid: false, reason: 'malformed' });
      }
      return res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({ valid: false });
    }
  }
}

